import { buildTree, type OptionTree } from "./tree";
import { type OptionEntry, opt, type Target } from "./types";

const index = (entries: OptionEntry[]): OptionTree =>
  buildTree(entries.map((entry) => ({ ...entry, segs: entry.path.split(".") })));

const content = ["gpt", "filesystem", "luks", "swap"];
const disk = "disko.devices.disk.*";
const part = `${disk}.content.partitions.*`;

// A small, stable catalog for tests; the real ones are generated by tools/catalog.
export const fixtures: Record<Target, OptionTree> = {
  nixos: index([
    opt("networking.hostName", "str"),
    opt("networking.firewall.enable", "bool"),
    opt("networking.firewall.allowedTCPPorts", "list", { values: ["int"] }),
    opt("mixed.value", "mix", { values: ["int", "str"] }),
    opt("mixed.text", "mix", { values: ["str", "list:str"] }),
    opt("mixed.jobs", "mix", { values: ["int", 'enum:["auto"]'] }),
    opt("services.openssh.enable", "bool"),
    opt("services.openssh.ports", "list"),
    opt("services.openssh.settings", "attrs"),
    opt("services.nginx.virtualHosts", "set"),
    opt("services.nginx.virtualHosts.*.root", "str"),
    opt("services.displayManager.gdm.enable", "bool"),
    opt("services.xserver.displayManager.gdm.enable", "bool", {
      renamedTo: "services.displayManager.gdm.enable",
    }),
    opt("boot.cleanTmpDir", "hidden"),
    opt("users.users", "set"),
    opt("users.users.*.isNormalUser", "bool"),
    opt("users.users.*.extraGroups", "list"),
    opt("users.users.*.description", "str"),
    opt("environment.variables", "attrs"),
    opt("system.stateVersion", "str"),
    opt("home-manager.users", "attrs"),
  ]),
  "home-manager": index([opt("home.stateVersion", "str"), opt("home.username", "str")]),
  disko: index([
    opt(`${disk}.device`, "str"),
    opt(`${disk}.type`, "enum", { values: ["disk"] }),
    opt(`${disk}.content`, "attrs"),
    opt(`${disk}.content.type`, "enum", { values: content }),
    opt(`${part}.size`, "str"),
    opt(`${part}.content.type`, "enum", { values: content }),
    opt(`${part}.content.format`, "str"),
    opt(`${part}.content.mountpoint`, "str"),
  ]),
  flake: index([
    opt("description", "str"),
    opt("inputs.*.url", "str"),
    opt("inputs.*.inputs.*.follows", "str"),
    opt("outputs", "any"),
    opt("nixConfig.bash-prompt", "str"),
  ]),
};
